Lemma FTState_guard_byte : forall m, (AFieldTabZero m \/ FT m) ->
  exists b0, rw_cells asegs m AG_FIELD_TABLE_GUARD (hg_cells b0 b0 (zeros 6)) /\ (b0 = 0 \/ b0 = 1)
             /\ (b0 = 0 -> AFieldTabZero m) /\ (b0 = 1 -> FT m).
Proof.
  intros m ST. destruct (FTState_cases m ST) as [[A B]|[A B]].
  - exists 0. split; [exact B|]. split; [lia|]. split; [| intros; lia]. intros _.
    destruct ST as [Z0|[C1 C2]]; [exact Z0|]. exfalso.
    unfold FTGuardCells in C2. pose proof (rw_cells_bytes_at _ _ _ _ B) as X. pose proof (rw_cells_bytes_at _ _ _ _ C2) as Y.
    destruct X as (_ & _ & X). destruct Y as (_ & _ & Y). specialize (X 0%nat ltac:(cbn; lia)). specialize (Y 0%nat ltac:(cbn; lia)).
    cbn in X, Y. rewrite X in Y. discriminate.
  - exists 1. split; [exact B|]. split; [lia|]. split; [intros; lia|]. intros _. apply FT_of_internal; assumption.
Qed.

